<?php
namespace App\Models;
use CodeIgniter\Model;
final class ReportingModel extends Model {
 private array $fix=['Antidiarrh?ique','AntidiarrhÃ©ique','AntipyrÃ©tique','Antipyr?tique']; private array $rep=['Antidiarrhéique','Antidiarrhéique','Antipyrétique','Antipyrétique'];
 public function homeStats(): array {$db=$this->db;return ['medicaments'=>(int)$db->query('SELECT COALESCE(SUM(Nombres),0) total FROM medicament WHERE id_client IS NOT NULL')->getRow()->total,'clients'=>(int)$db->query('SELECT COUNT(*) total FROM client')->getRow()->total,'types'=>(int)$db->query('SELECT COUNT(DISTINCT Type) total FROM medicament WHERE id_client IS NOT NULL')->getRow()->total,'mois'=>(int)$db->query("SELECT COUNT(DISTINCT DATE_FORMAT(Date,'%Y-%m')) total FROM medicament WHERE Date != '0000-00-00 00:00:00'")->getRow()->total];}
 public function analytics(): array {$db=$this->db;$medicaments=[];$totalMeds=0;foreach($db->query('SELECT Type,SUM(Nombres) Nombre FROM medicament WHERE id_client IS NOT NULL GROUP BY Type')->getResultArray() as $r){$r['Type']=str_replace($this->fix,$this->rep,$r['Type']);$r['Nombre']=(int)$r['Nombre'];$medicaments[]=$r;$totalMeds+=$r['Nombre'];}$clients=[];$totalClients=0;foreach($db->query('SELECT Type,COUNT(*) Nombre FROM client GROUP BY Type')->getResultArray() as $r){$r['Type']=str_replace('Hospitalis?','Hospitalisé',$r['Type']);$r['Nombre']=(int)$r['Nombre'];$clients[]=$r;$totalClients+=$r['Nombre'];}$months=[];$types=[];$monthly=[];foreach($db->query("SELECT DATE_FORMAT(Date,'%Y-%m') Mois,Type,SUM(Nombres) Total FROM medicament WHERE Date!='0000-00-00 00:00:00' GROUP BY Mois,Type ORDER BY Mois,Type")->getResultArray() as $r){$r['Type']=str_replace($this->fix,$this->rep,$r['Type']);$r['Total']=(int)$r['Total'];$monthly[]=$r;$months[]=$r['Mois'];$types[]=$r['Type'];}$months=array_values(array_unique($months));$types=array_values(array_unique($types));$ages=$db->query("SELECT Age,Genre,COUNT(*) Total FROM client WHERE Age!='0' GROUP BY Age,Genre ORDER BY Age,Genre")->getResultArray();foreach($ages as &$r)$r['Total']=(int)$r['Total'];return compact('medicaments','clients','monthly','ages','totalMeds','totalClients','months','types');}
 public function pivotData(): array{return $this->db->query("SELECT c.Id,c.Age,c.Genre,c.Type TypeClient,c.District,m.id_client,m.Type TypeMedicament,m.Nombres Quantite,DATE_FORMAT(m.Date,'%Y-%m') Mois FROM client c INNER JOIN medicament m ON c.Id=m.id_client ORDER BY m.Date DESC")->getResultArray();}
 public function riskRows(): array{return $this->db->query("SELECT c.District,m.Type,SUM(m.Nombres) total FROM medicament m INNER JOIN client c ON c.Id=m.id_client WHERE c.District != '' AND m.Date != '0000-00-00 00:00:00' GROUP BY c.District,m.Type")->getResultArray();}
}
